CREATE TABLE users (id TEXT PRIMARY KEY NOT NULL, display_name TEXT NOT NULL, disabled INTEGER NOT NULL DEFAULT 0 CHECK (disabled IN (0, 1)));
CREATE TABLE sources (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), url_ciphertext TEXT NOT NULL, url_fingerprint TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 0 CHECK (revision >= 0), UNIQUE (user_id, url_fingerprint), UNIQUE (id, user_id));
CREATE TABLE episodes (source_id TEXT NOT NULL REFERENCES sources(id), identity TEXT NOT NULL, published_at TEXT NOT NULL, title TEXT NOT NULL, PRIMARY KEY (source_id, identity));
CREATE TRIGGER episodes_insert_revision AFTER INSERT ON episodes BEGIN UPDATE sources SET revision = revision + 1 WHERE id = NEW.source_id; END;
CREATE TRIGGER episodes_update_revision AFTER UPDATE ON episodes BEGIN UPDATE sources SET revision = revision + 1 WHERE id = NEW.source_id; END;
CREATE TABLE subscriptions (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), source_id TEXT NOT NULL, schedule_json TEXT NOT NULL CHECK (json_valid(schedule_json)), selection_json TEXT NOT NULL CHECK (json_valid(selection_json)), live INTEGER NOT NULL CHECK (live IN (0, 1)), paused INTEGER NOT NULL DEFAULT 0 CHECK (paused IN (0, 1)), next_slot TEXT NOT NULL, waiting INTEGER NOT NULL DEFAULT 0 CHECK (waiting IN (0, 1)), revision INTEGER NOT NULL DEFAULT 0 CHECK (revision >= 0), publication_version INTEGER NOT NULL DEFAULT 0 CHECK (publication_version >= 0), mutation_id TEXT, FOREIGN KEY (source_id, user_id) REFERENCES sources(id, user_id), UNIQUE (user_id, source_id), UNIQUE (id, source_id));
CREATE INDEX subscriptions_due ON subscriptions(paused, next_slot);
CREATE TABLE releases (subscription_id TEXT NOT NULL, source_id TEXT NOT NULL, episode_identity TEXT NOT NULL, delivered_at TEXT NOT NULL, sequence INTEGER NOT NULL CHECK (sequence > 0), output_guid TEXT NOT NULL UNIQUE, PRIMARY KEY (subscription_id, episode_identity), UNIQUE (subscription_id, sequence), FOREIGN KEY (subscription_id, source_id) REFERENCES subscriptions(id, source_id), FOREIGN KEY (source_id, episode_identity) REFERENCES episodes(source_id, identity));
CREATE TRIGGER releases_no_update BEFORE UPDATE ON releases BEGIN SELECT RAISE(ABORT, 'Delivery history is immutable'); END;
CREATE TRIGGER releases_no_delete BEFORE DELETE ON releases BEGIN SELECT RAISE(ABORT, 'Delivery history is immutable'); END;
CREATE TABLE publication_outbox (subscription_id TEXT PRIMARY KEY NOT NULL REFERENCES subscriptions(id), desired_version INTEGER NOT NULL CHECK (desired_version >= 0), published_version INTEGER NOT NULL DEFAULT -1 CHECK (published_version >= -1), attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0), CHECK (published_version <= desired_version));
CREATE TRIGGER delivered_metadata_dirty AFTER UPDATE ON episodes WHEN OLD.title IS NOT NEW.title OR OLD.published_at IS NOT NEW.published_at BEGIN UPDATE subscriptions SET publication_version = publication_version + 1, revision = revision + 1 WHERE id IN (SELECT subscription_id FROM releases WHERE source_id = NEW.source_id AND episode_identity = NEW.identity); UPDATE publication_outbox SET desired_version = (SELECT publication_version FROM subscriptions WHERE id = subscription_id) WHERE subscription_id IN (SELECT subscription_id FROM releases WHERE source_id = NEW.source_id AND episode_identity = NEW.identity); END;
CREATE TRIGGER releases_no_replace BEFORE INSERT ON releases WHEN EXISTS (SELECT 1 FROM releases WHERE (subscription_id = NEW.subscription_id AND (episode_identity = NEW.episode_identity OR sequence = NEW.sequence)) OR output_guid = NEW.output_guid) BEGIN SELECT RAISE(ABORT, 'Delivery history cannot be replaced'); END;
